=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md: holding registers for
// AW and W, READY computed from state only, one outstanding transaction per
// direction, 1-cycle response latency, SLVERR for unmapped (misaligned)
// addresses, synchronous active-low reset.
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                      aclk,
    input  wire                      aresetn,
    input  wire [ADDR_WIDTH-1:0]     s_axil_awaddr,
    input  wire                      s_axil_awvalid,
    output wire                      s_axil_awready,
    input  wire [DATA_WIDTH-1:0]     s_axil_wdata,
    input  wire [(DATA_WIDTH/8)-1:0] s_axil_wstrb,
    input  wire                      s_axil_wvalid,
    output wire                      s_axil_wready,
    output wire [1:0]                s_axil_bresp,
    output wire                      s_axil_bvalid,
    input  wire                      s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]     s_axil_araddr,
    input  wire                      s_axil_arvalid,
    output wire                      s_axil_arready,
    output wire [DATA_WIDTH-1:0]     s_axil_rdata,
    output wire [1:0]                s_axil_rresp,
    output wire                      s_axil_rvalid,
    input  wire                      s_axil_rready
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;
    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg                  w_held_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [DATA_WIDTH-1:0] rdata_q;
    reg [DATA_WIDTH-1:0] reg0_q;
    reg [DATA_WIDTH-1:0] reg1_q;
    reg [DATA_WIDTH-1:0] reg2_q;
    reg [DATA_WIDTH-1:0] reg3_q;

    // Datapath holding registers (not reset; qualified by the held flags).
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [DATA_WIDTH-1:0] w_data_q;
    reg [STRB_WIDTH-1:0] w_strb_q;

    // Next-state values
    reg                  aw_held_d;
    reg                  w_held_d;
    reg                  bvalid_d;
    reg [1:0]            bresp_d;
    reg                  rvalid_d;
    reg [1:0]            rresp_d;
    reg [DATA_WIDTH-1:0] rdata_d;
    reg [DATA_WIDTH-1:0] reg0_d;
    reg [DATA_WIDTH-1:0] reg1_d;
    reg [DATA_WIDTH-1:0] reg2_d;
    reg [DATA_WIDTH-1:0] reg3_d;
    reg [DATA_WIDTH-1:0] rd_sel;

    // ------------------------------------------------------------------
    // Handshakes: READY depends on state only
    // ------------------------------------------------------------------
    assign s_axil_awready = ~aw_held_q & ~bvalid_q;
    assign s_axil_wready  = ~w_held_q & ~bvalid_q;
    assign s_axil_arready = ~rvalid_q;

    assign s_axil_bvalid = bvalid_q;
    assign s_axil_bresp  = bresp_q;
    assign s_axil_rvalid = rvalid_q;
    assign s_axil_rresp  = rresp_q;
    assign s_axil_rdata  = rdata_q;

    wire aw_hs = s_axil_awvalid & s_axil_awready;
    wire w_hs  = s_axil_wvalid & s_axil_wready;
    wire ar_hs = s_axil_arvalid & s_axil_arready;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held_q | aw_hs) & (w_held_q | w_hs);

    // Held copy when one exists, else the live bus.
    wire [ADDR_WIDTH-1:0] wr_addr;
    wire [DATA_WIDTH-1:0] wr_data;
    wire [STRB_WIDTH-1:0] wr_strb;
    assign wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    assign wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
    assign wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: mapped when word aligned and within 0x0..0xC
    // ------------------------------------------------------------------
    wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    // ------------------------------------------------------------------
    // Byte-enable merge
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar gi;
    generate
        for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_wr_mask
            assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] reg0_m;
    wire [DATA_WIDTH-1:0] reg1_m;
    wire [DATA_WIDTH-1:0] reg2_m;
    wire [DATA_WIDTH-1:0] reg3_m;
    assign reg0_m = (reg0_q & ~wr_mask) | (wr_data & wr_mask);
    assign reg1_m = (reg1_q & ~wr_mask) | (wr_data & wr_mask);
    assign reg2_m = (reg2_q & ~wr_mask) | (wr_data & wr_mask);
    assign reg3_m = (reg3_q & ~wr_mask) | (wr_data & wr_mask);

    // ------------------------------------------------------------------
    // Read data select
    // ------------------------------------------------------------------
    always @* begin
        rd_sel = {DATA_WIDTH{1'b0}};
        case (s_axil_araddr[3:2])
            2'd0:    rd_sel = reg0_q;
            2'd1:    rd_sel = reg1_q;
            2'd2:    rd_sel = reg2_q;
            2'd3:    rd_sel = reg3_q;
            default: rd_sel = {DATA_WIDTH{1'b0}};
        endcase
    end

    // ------------------------------------------------------------------
    // Next-state logic
    // ------------------------------------------------------------------
    always @* begin
        aw_held_d = aw_held_q;
        w_held_d  = w_held_q;
        bvalid_d  = bvalid_q;
        bresp_d   = bresp_q;
        rvalid_d  = rvalid_q;
        rresp_d   = rresp_q;
        rdata_d   = rdata_q;
        reg0_d    = reg0_q;
        reg1_d    = reg1_q;
        reg2_d    = reg2_q;
        reg3_d    = reg3_q;

        // Write side
        if (bvalid_q && s_axil_bready) begin
            bvalid_d = 1'b0;
        end
        if (aw_hs) begin
            aw_held_d = 1'b1;
        end
        if (w_hs) begin
            w_held_d = 1'b1;
        end
        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
            bvalid_d  = 1'b1;
            bresp_d   = wr_mapped ? RESP_OKAY : RESP_SLVERR;
            if (wr_mapped) begin
                case (wr_addr[3:2])
                    2'd0:    reg0_d = reg0_m;
                    2'd1:    reg1_d = reg1_m;
                    2'd2:    reg2_d = reg2_m;
                    2'd3:    reg3_d = reg3_m;
                    default: reg0_d = reg0_q;
                endcase
            end
        end

        // Read side
        if (rvalid_q && s_axil_rready) begin
            rvalid_d = 1'b0;
        end
        if (ar_hs) begin
            rvalid_d = 1'b1;
            rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
            rdata_d  = rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
        end
    end

    // ------------------------------------------------------------------
    // State registers (synchronous, active-low reset)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            w_held_q  <= 1'b0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rresp_q   <= RESP_OKAY;
            rdata_q   <= {DATA_WIDTH{1'b0}};
            reg0_q    <= {DATA_WIDTH{1'b0}};
            reg1_q    <= {DATA_WIDTH{1'b0}};
            reg2_q    <= {DATA_WIDTH{1'b0}};
            reg3_q    <= {DATA_WIDTH{1'b0}};
        end else begin
            aw_held_q <= aw_held_d;
            w_held_q  <= w_held_d;
            bvalid_q  <= bvalid_d;
            bresp_q   <= bresp_d;
            rvalid_q  <= rvalid_d;
            rresp_q   <= rresp_d;
            rdata_q   <= rdata_d;
            reg0_q    <= reg0_d;
            reg1_q    <= reg1_d;
            reg2_q    <= reg2_d;
            reg3_q    <= reg3_d;
        end
    end

    // Holding registers: load enable only.
    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

`ifdef FORMAL
    // Design-intent properties (handshake rules of interface_spec.md 4 and 8).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Manager assumptions
    always @(*) begin
        if (!f_past_valid) assume (!aresetn);
        if (!aresetn) begin
            assume (!s_axil_awvalid);
            assume (!s_axil_wvalid);
            assume (!s_axil_arvalid);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready))
                assume (s_axil_awvalid && (s_axil_awaddr == $past(s_axil_awaddr)));
            if ($past(s_axil_wvalid && !s_axil_wready))
                assume (s_axil_wvalid && (s_axil_wdata == $past(s_axil_wdata))
                        && (s_axil_wstrb == $past(s_axil_wstrb)));
            if ($past(s_axil_arvalid && !s_axil_arready))
                assume (s_axil_arvalid && (s_axil_araddr == $past(s_axil_araddr)));
        end
    end

    // Subordinate assertions
    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn)) begin
            assert (!bvalid_q);
            assert (!rvalid_q);
            assert (!aw_held_q);
            assert (!w_held_q);
        end
        if (f_past_valid && $past(aresetn)) begin
            if ($past(bvalid_q && !s_axil_bready))
                assert (bvalid_q && (bresp_q == $past(bresp_q)));
            if ($past(rvalid_q && !s_axil_rready))
                assert (rvalid_q && (rresp_q == $past(rresp_q))
                        && (rdata_q == $past(rdata_q)));
            if ($past(do_write))
                assert (bvalid_q && (bresp_q == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR)));
            else if (!$past(bvalid_q))
                assert (!bvalid_q);
            if ($past(ar_hs))
                assert (rvalid_q && (rresp_q == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR)));
            else if (!$past(rvalid_q))
                assert (!rvalid_q);
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (!(aw_held_q && w_held_q));
            assert (!(bvalid_q && (aw_held_q || w_held_q)));
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (bvalid_q && s_axil_bready);
            cover (rvalid_q && s_axil_rready);
        end
    end
`endif

endmodule
=== END FILE ===
