// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven after the falling edge; handshakes are decided before
// the rising edge (READY depends only on state, so it is stable then).
`define CHK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error("FAIL at %0t: %s", $time, msg); end end

module axi4_lite_regs_tb;

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    reg         aclk;
    reg         aresetn;
    reg  [3:0]  awaddr;
    reg         awvalid;
    wire        awready;
    reg  [31:0] wdata;
    reg  [3:0]  wstrb;
    reg         wvalid;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    reg         bready;
    reg  [3:0]  araddr;
    reg         arvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    reg         rready;

    integer passed;
    integer failed;
    integer got_nonce;
    reg [8*64-1:0] nonce;
    reg [31:0] model [0:3];

    axi4_lite_regs #(.ADDR_WIDTH(4), .DATA_WIDTH(32)) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready)
    );

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    function [31:0] merge_f(input [31:0] old, input [31:0] data, input [3:0] strb);
        reg [31:0] m;
        begin
            m = {{8{strb[3]}}, {8{strb[2]}}, {8{strb[1]}}, {8{strb[0]}}};
            merge_f = (old & ~m) | (data & m);
        end
    endfunction

    function mapped_f(input [3:0] a);
        begin
            mapped_f = (a[1:0] == 2'b00);
        end
    endfunction

    // One write. Called and returns at a falling edge.
    task write_txn(input [3:0] addr, input [31:0] data, input [3:0] strb,
                   input integer aw_dly, input integer w_dly, input integer b_stall);
        reg aw_done;
        reg w_done;
        reg aw_fire;
        reg w_fire;
        reg [1:0] exp_resp;
        reg [1:0] held_resp;
        integer cyc;
        integer lat;
        integer s;
        begin
            exp_resp = mapped_f(addr) ? RESP_OKAY : RESP_SLVERR;
            aw_done = 1'b0;
            w_done  = 1'b0;
            cyc = 0;
            while (!(aw_done && w_done)) begin
                if (!aw_done && (cyc >= aw_dly)) begin
                    awvalid = 1'b1;
                    awaddr  = addr;
                end
                if (!w_done && (cyc >= w_dly)) begin
                    wvalid = 1'b1;
                    wdata  = data;
                    wstrb  = strb;
                end
                #1;
                `CHK(!bvalid, "BVALID before both AW and W accepted")
                aw_fire = awvalid & awready;
                w_fire  = wvalid & wready;
                @(posedge aclk);
                @(negedge aclk);
                if (aw_fire) begin
                    aw_done = 1'b1;
                    awvalid = 1'b0;
                    awaddr  = 4'hF;
                end
                if (w_fire) begin
                    w_done = 1'b1;
                    wvalid = 1'b0;
                    wdata  = 32'hDEAD_BEEF;
                    wstrb  = 4'hF;
                end
                if (aw_done && !w_done) begin
                    `CHK(!awready, "AWREADY high while address is held")
                end
                if (w_done && !aw_done) begin
                    `CHK(!wready, "WREADY high while data is held")
                end
                cyc = cyc + 1;
                if (!(aw_done && w_done) && (cyc > 50)) begin
                    `CHK(1'b0, "write request never accepted")
                    aw_done = 1'b1;
                    w_done  = 1'b1;
                end
            end
            lat = 1;
            while (!bvalid && (lat < 10)) begin
                @(posedge aclk);
                @(negedge aclk);
                lat = lat + 1;
            end
            `CHK(bvalid, "BVALID never rose")
            `CHK(lat <= 2, "write latency above the 2-cycle bound")
            `CHK(lat == 1, "write latency is not 1 cycle")
            `CHK(!awready && !wready, "AW or W ready while B pending")
            held_resp = bresp;
            for (s = 0; s < b_stall; s = s + 1) begin
                @(posedge aclk);
                @(negedge aclk);
                `CHK(bvalid, "BVALID dropped under backpressure")
                `CHK(bresp == held_resp, "BRESP changed under backpressure")
                `CHK(!awready && !wready, "AW or W ready while B stalled")
            end
            `CHK(bresp == exp_resp, "BRESP mismatch")
            bready = 1'b1;
            @(posedge aclk);
            @(negedge aclk);
            bready = 1'b0;
            `CHK(!bvalid, "BVALID not cleared after handshake")
            `CHK(awready && wready, "write channel not ready the cycle after B taken")
            if (mapped_f(addr)) begin
                model[addr[3:2]] = merge_f(model[addr[3:2]], data, strb);
            end
        end
    endtask

    // One read. Called and returns at a falling edge.
    task read_txn(input [3:0] addr, input integer ar_dly, input integer r_stall);
        reg ar_done;
        reg ar_fire;
        reg [31:0] exp_data;
        reg [31:0] held_data;
        reg [1:0] exp_resp;
        reg [1:0] held_resp;
        integer cyc;
        integer lat;
        integer s;
        begin
            if (mapped_f(addr)) begin
                exp_data = model[addr[3:2]];
                exp_resp = RESP_OKAY;
            end else begin
                exp_data = 32'h0;
                exp_resp = RESP_SLVERR;
            end
            ar_done = 1'b0;
            cyc = 0;
            while (!ar_done) begin
                if (cyc >= ar_dly) begin
                    arvalid = 1'b1;
                    araddr  = addr;
                end
                #1;
                `CHK(!rvalid, "RVALID before AR accepted")
                ar_fire = arvalid & arready;
                @(posedge aclk);
                @(negedge aclk);
                if (ar_fire) begin
                    ar_done = 1'b1;
                    arvalid = 1'b0;
                    araddr  = 4'hF;
                end
                cyc = cyc + 1;
                if (!ar_done && (cyc > 50)) begin
                    `CHK(1'b0, "read address never accepted")
                    ar_done = 1'b1;
                end
            end
            lat = 1;
            while (!rvalid && (lat < 10)) begin
                @(posedge aclk);
                @(negedge aclk);
                lat = lat + 1;
            end
            `CHK(rvalid, "RVALID never rose")
            `CHK(lat <= 2, "read latency above the 2-cycle bound")
            `CHK(lat == 1, "read latency is not 1 cycle")
            `CHK(!arready, "ARREADY high while R pending")
            held_data = rdata;
            held_resp = rresp;
            for (s = 0; s < r_stall; s = s + 1) begin
                @(posedge aclk);
                @(negedge aclk);
                `CHK(rvalid, "RVALID dropped under backpressure")
                `CHK(rdata == held_data, "RDATA changed under backpressure")
                `CHK(rresp == held_resp, "RRESP changed under backpressure")
                `CHK(!arready, "ARREADY high while R stalled")
            end
            `CHK(rdata == exp_data, "RDATA mismatch")
            `CHK(rresp == exp_resp, "RRESP mismatch")
            rready = 1'b1;
            @(posedge aclk);
            @(negedge aclk);
            rready = 1'b0;
            `CHK(!rvalid, "RVALID not cleared after handshake")
            `CHK(arready, "read channel not ready the cycle after R taken")
        end
    endtask

    // A write and a read accepted on the same clock (mapped, different registers).
    task rw_same_cycle(input [3:0] waddr, input [31:0] wd, input [3:0] raddr);
        reg [31:0] exp_rd;
        begin
            exp_rd  = model[raddr[3:2]];
            awvalid = 1'b1;
            awaddr  = waddr;
            wvalid  = 1'b1;
            wdata   = wd;
            wstrb   = 4'hF;
            arvalid = 1'b1;
            araddr  = raddr;
            #1;
            `CHK(awready && wready && arready, "not all channels ready for simultaneous access")
            @(posedge aclk);
            @(negedge aclk);
            awvalid = 1'b0;
            wvalid  = 1'b0;
            arvalid = 1'b0;
            awaddr  = 4'hF;
            araddr  = 4'hF;
            `CHK(bvalid, "BVALID missing after simultaneous write")
            `CHK(rvalid, "RVALID missing after simultaneous read")
            `CHK(bresp == RESP_OKAY, "BRESP not OKAY for simultaneous write")
            `CHK(rresp == RESP_OKAY, "RRESP not OKAY for simultaneous read")
            `CHK(rdata == exp_rd, "RDATA mismatch for simultaneous read")
            model[waddr[3:2]] = wd;
            rready = 1'b1;
            @(posedge aclk);
            @(negedge aclk);
            rready = 1'b0;
            `CHK(!rvalid, "RVALID not cleared")
            `CHK(bvalid, "BVALID lost while R was taken")
            `CHK(bresp == RESP_OKAY, "BRESP changed while stalled")
            bready = 1'b1;
            @(posedge aclk);
            @(negedge aclk);
            bready = 1'b0;
            `CHK(!bvalid, "BVALID not cleared")
            `CHK(awready && wready && arready, "channels not ready after simultaneous access")
        end
    endtask

    task read_all;
        begin
            read_txn(4'h0, 0, 0);
            read_txn(4'h4, 0, 0);
            read_txn(4'h8, 0, 0);
            read_txn(4'hC, 0, 0);
        end
    endtask

    // Watchdog
    initial begin
        #200000;
        failed = failed + 1;
        $error("FAIL: simulation timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        passed = 0;
        failed = 0;
        nonce = {(8*64){1'b0}};
        got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got_nonce == 0) nonce = {(8*64){1'b0}};

        aresetn = 1'b0;
        awaddr  = 4'h0;
        awvalid = 1'b0;
        wdata   = 32'h0;
        wstrb   = 4'h0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = 4'h0;
        arvalid = 1'b0;
        rready  = 1'b0;
        model[0] = 32'h0;
        model[1] = 32'h0;
        model[2] = 32'h0;
        model[3] = 32'h0;

        // ---------------- Reset values ----------------
        repeat (3) @(posedge aclk);
        @(negedge aclk);
        `CHK(!bvalid, "BVALID high in reset")
        `CHK(!rvalid, "RVALID high in reset")
        aresetn = 1'b1;
        `CHK(awready && wready && arready, "READY low after reset")
        read_all;

        // ---------------- Write then read every register, all orders -----
        write_txn(4'h0, 32'h1111_1111, 4'hF, 0, 0, 0); // AW and W together
        write_txn(4'h4, 32'h2222_2222, 4'hF, 0, 3, 0); // AW before W
        write_txn(4'h8, 32'h3333_3333, 4'hF, 2, 0, 0); // W before AW
        write_txn(4'hC, 32'h4444_4444, 4'hF, 2, 2, 0); // both late, same cycle
        read_all;

        // ---------------- Byte strobes ----------------
        write_txn(4'h0, 32'hAABB_CCDD, 4'b0101, 0, 0, 0);
        `CHK(model[0] == 32'h11BB_11DD, "model sanity for partial strobe")
        write_txn(4'h0, 32'hEE00_0000, 4'b1000, 0, 1, 0);
        write_txn(4'h0, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0); // empty strobe: no change, OKAY
        write_txn(4'hC, 32'h0000_9900, 4'b0010, 1, 0, 0);
        read_txn(4'h0, 0, 0);
        read_txn(4'hC, 0, 0);

        // ---------------- B and R backpressure ----------------
        write_txn(4'h4, 32'h5A5A_A5A5, 4'hF, 0, 2, 5);
        write_txn(4'h8, 32'h0F0F_F0F0, 4'hF, 3, 0, 3);
        read_txn(4'h4, 0, 6);
        read_txn(4'h8, 2, 3);

        // ---------------- SLVERR policy ----------------
        write_txn(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 2);
        write_txn(4'hE, 32'hFFFF_FFFF, 4'hF, 1, 0, 0);
        write_txn(4'h3, 32'hFFFF_FFFF, 4'hF, 0, 1, 0);
        read_txn(4'h1, 0, 0);
        read_txn(4'hE, 0, 2);
        read_txn(4'h7, 1, 0);
        read_all; // unmapped writes changed nothing

        // ---------------- Back-to-back transactions ----------------
        write_txn(4'h0, 32'h0000_0001, 4'hF, 0, 0, 0);
        write_txn(4'h4, 32'h0000_0002, 4'hF, 0, 0, 0);
        write_txn(4'h8, 32'h0000_0003, 4'hF, 0, 0, 0);
        write_txn(4'hC, 32'h0000_0004, 4'hF, 0, 0, 0);
        read_txn(4'hC, 0, 0);
        read_txn(4'h8, 0, 0);
        read_txn(4'h4, 0, 0);
        read_txn(4'h0, 0, 0);
        write_txn(4'h4, 32'h1234_5678, 4'hF, 0, 0, 0);
        read_txn(4'h4, 0, 0);
        write_txn(4'h4, 32'h8765_4321, 4'hF, 0, 0, 0);
        read_txn(4'h4, 0, 0);

        // ---------------- Read and write on the same clock ----------------
        rw_same_cycle(4'h4, 32'hCAFE_0001, 4'h8);
        read_txn(4'h4, 0, 0);

        // ---------------- Reset during traffic ----------------
        // Accept AW only (half write) and a read whose R is left stalled.
        awvalid = 1'b1;
        awaddr  = 4'h8;
        arvalid = 1'b1;
        araddr  = 4'h4;
        #1;
        `CHK(awready && arready, "AW/AR not ready before reset test")
        @(posedge aclk);
        @(negedge aclk);
        awvalid = 1'b0;
        arvalid = 1'b0;
        awaddr  = 4'hF;
        araddr  = 4'hF;
        `CHK(!bvalid, "BVALID after AW alone")
        `CHK(rvalid, "RVALID missing before reset")
        `CHK(!awready && wready, "held-address READY state wrong")
        aresetn = 1'b0;
        @(posedge aclk);
        @(negedge aclk);
        @(posedge aclk);
        @(negedge aclk);
        `CHK(!bvalid && !rvalid, "responses not cleared by reset")
        `CHK(awready && wready && arready, "READY not restored by reset")
        aresetn = 1'b1;
        model[0] = 32'h0;
        model[1] = 32'h0;
        model[2] = 32'h0;
        model[3] = 32'h0;
        read_all;
        // W first: a stale held AW would pair with it and raise BVALID early.
        write_txn(4'hC, 32'hCAFE_F00D, 4'hF, 3, 0, 0);
        read_txn(4'h8, 0, 0);
        read_txn(4'hC, 0, 0);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
